const records = $input.first().json.records || [];
const now = new Date();

function text(value) {
  if (Array.isArray(value)) return value.map(v => typeof v === 'object' ? JSON.stringify(v) : String(v ?? '')).join(' ').trim();
  return String(value ?? '').trim();
}

function addWeekdayHours(start, hours) {
  const d = new Date(start);
  let remaining = hours;
  while (remaining > 0) {
    d.setHours(d.getHours() + 1);
    const day = d.getDay();
    if (day !== 0 && day !== 6) remaining -= 1;
  }
  return d;
}

const copyMap = [
  ['Subject Line Email 1 (Review)', 'Campaign Subject 1 Version 1'],
  ['Script Copy Email 1 (Review)', 'Campaign Body 1 Version 1'],
  ['Subject Line Email 2 (Review)', 'Campaign Subject 2 Version 1'],
  ['Script Copy Email 2 (Review)', 'Campaign Body 2 Version 1'],
  ['Subject Line Email 3 (Review)', 'Campaign Subject 3 Version 1'],
  ['Script Copy Email 3 (Review)', 'Campaign Body 3 Version 1'],
  ['Subject Line Email 4 (Review)', 'Campaign Email 4 Subject'],
  ['Script Copy Email 4 (Review)', 'Campaign Body 4 Version 1'],
];

const output = [];
for (const record of records) {
  const f = record.fields || {};
  const feedback = text(f["Client's Feedback"]);
  const requestedChanges = text(f['Select Changes']);
  if (feedback || requestedChanges) continue;

  const submittedAt = f['Client Review Submitted At'];
  const dueAt = f['Client Review Auto-Approve At'];

  if (!submittedAt || !dueAt) {
    const submitted = now.toISOString();
    output.push({json:{id:record.id,action:'timer_started',fields:{
      'Client Review Submitted At': submitted,
      'Client Review Auto-Approve At': addWeekdayHours(now, 48).toISOString(),
    }}});
    continue;
  }

  if (new Date(dueAt).getTime() > now.getTime()) continue;

  const updates = {
    'Workflow Stage': 'Approved',
    'Campaign Approval Source': 'Auto-approved after 48 business hours',
  };
  for (const [source, target] of copyMap) {
    if (text(f[source])) updates[target] = f[source];
  }
  output.push({json:{id:record.id,action:'auto_approved',fields:updates}});
}
return output;
